def sum_of_scores(n: int, m: int) -> int:
    """ Calculate the sum of scores of all good sequences modulo 998244353.

    A good sequence is an integer sequence of length between 1 and n (inclusive),
    where each element is between 1 and m (inclusive).

    The score of a good sequence is the number of positive divisors of X,
    where X is the product of all elements in the sequence.

    The function computes the sum of scores of all possible good sequences.
    There are sum(m^k for k in range(1, n+1)) such sequences in total.

    Args:
        n: Maximum length of sequences (1 <= n <= 10^18)
        m: Maximum value of elements (1 <= m <= 16)

    Returns:
        The sum of all scores modulo 998244353
    """
    MOD = 998244353

    if m == 1:
        return n % MOD

    primes = [2, 3, 5, 7, 11, 13]
    num_primes = len(primes)

    def get_v_p(x, p):
        count = 0
        while x > 0 and x % p == 0:
            count += 1
            x //= p
        return count

    # W[S] = sum_{x=1}^m prod_{p_i in S} v_{p_i}(x)
    W = [0] * (1 << num_primes)
    for mask in range(1 << num_primes):
        s_val = 0
        for x in range(1, m + 1):
            prod = 1
            for i in range(num_primes):
                if (mask >> i) & 1:
                    prod *= get_v_p(x, primes[i])
            s_val += prod
        W[mask] = s_val % MOD

    size = 1 << num_primes

    def mat_mul(A, B, sz):
        C = [[0] * sz for _ in range(sz)]
        for i in range(sz):
            row_A = A[i]
            for k in range(sz):
                val_A = row_A[k]
                if val_A == 0: continue
                row_B = B[k]
                for j in range(sz):
                    C[i][j] = (C[i][j] + val_A * row_B[j]) % MOD
        return C

    M_prime = [[0] * size for _ in range(size)]
    for s in range(size):
        for t in range(size):
            if (s & t) == t:
                M_prime[s][t] = W[s ^ t]

    # B is (size + 1) x (size + 1)
    B_size = size + 1
    B = [[0] * B_size for _ in range(B_size)]
    for s in range(size):
        for t in range(size):
            B[s][t] = M_prime[s][t]

    # Bottom row: B[size][t] = sum_s M_prime[s][t]
    for t in range(size):
        col_sum = 0
        for s in range(size):
            col_sum = (col_sum + M_prime[s][t]) % MOD
        B[size][t] = col_sum

    B[size][size] = 1

    def mat_pow(A, p, sz):
        res = [[0] * sz for _ in range(sz)]
        for i in range(sz):
            res[i][i] = 1
        while p > 0:
            if p % 2 == 1:
                res = mat_mul(res, A, sz)
            A = mat_mul(A, A, sz)
            p //= 2
        return res

    B_n = mat_pow(B, n, B_size)

    # Result is (B^n)_{size, 0}
    return B_n[size][0]

