def count_valid_grids(H: int, W: int, grid: list[str]) -> int:
    """ Given a grid with H rows and W columns consisting of '1', '2', '3', and '?',
    count how many ways we can replace each '?' with '1', '2', or ' cubed such that
    any two adjacent (edge-sharing) cells contain different digits.

    Return the count modulo 998244353.

    Args:
        H: Number of rows (1 <= H, H * W <= 200)
        W: Number of columns (1 <= W, H * W <= 200)
        grid: List of strings representing the grid, where grid[i] is the i-th row

    Returns:
        The number of valid grid configurations modulo 998244353
    """
    MOD = 998244353

    # Transpose if W > H to ensure W is the smaller dimension
    if W > H:
        new_grid = [['?' for _ in range(H)] for _ in range(W)]
        for r in range(H):
            for c in range(W):
                new_grid[c][r] = grid[r][c]
        grid = [''.join(row) for row in new_grid]
        H, W = W, H

    # DP state: tuple of W colors (0, 1, or 2)
    # We use -1 to represent "no color" for the initial boundary (row -1)
    dp = {(-1,) * W: 1}

    for r in range(H):
        for c in range(W):
            new_dp = {}
            char = grid[r][c]

            # Possible colors for this cell
            if char == '1':
                possible_colors = (0,)
            elif char == '2':
                possible_colors = (1,)
            elif char == '3':
                possible_colors = (2,)
            else:
                possible_colors = (0, 1, 2)

            for state, count in dp.items():
                above_color = state[c]
                left_color = state[c-1] if c > 0 else -1

                for color in possible_colors:
                    if color != above_color and color != left_color:
                        # Update state: replace the color of the cell we just processed
                        new_state = list(state)
                        new_state[c] = color
                        new_state_tuple = tuple(new_state)
                        new_dp[new_state_tuple] = (new_dp.get(new_state_tuple, 0) + count) % MOD
            dp = new_dp

    return sum(dp.values()) % MOD

