from typing import List, Tuple


def can_tile_grid(n: int, h: int, w: int, tiles: List[Tuple[int, int]]) -> bool:
    """ Determine if it's possible to place rectangular tiles on an H×W grid such that:
    - Every cell is covered by exactly one tile
    - Tiles can be rotated (so a 2×3 tile can be placed as 3×2)
    - Some tiles may remain unused
    - Tiles must be aligned with grid cells and cannot extend outside

    Args:
        n: Number of available tiles (1 ≤ n ≤ 7)
        h: Height of the grid (1 ≤ h ≤ 10)
        w: Width of the grid (1 ≤ w ≤ 10)
        tiles: List of (a, b) tuples where tile i has dimensions a×b (1 ≤ a, b ≤ 10)

    Returns:
        True if the grid can be perfectly tiled, False otherwise

    >>> can_tile_grid(5, 5, 5, [(1, 1), (3, 3), (4, 4), (2, 3), (2, 5)])
    True
    >>> can_tile_grid(1, 1, 2, [(2, 3)])
    False
    >>> can_tile_grid(1, 2, 2, [(1, 1)])
    False
    """
    grid = [[False for _ in range(w)] for _ in range(h)]
    used = [False] * n

    def solve():
        # Find the first empty cell
        r, c = -1, -1
        for i in range(h):
            for j in range(w):
                if not grid[i][j]:
                    r, c = i, j
                    break
            if r != -1:
                break

        if r == -1:
            return True

        # Try placing each available tile
        for i in range(n):
            if not used[i]:
                a_orig, b_orig = tiles[i]
                # Try orientation 1: (a_orig, b_orig)
                a, b = a_orig, b_orig
                if r + a <= h and c + b <= w:
                    possible = True
                    for dr in range(a):
                        for dc in range(b):
                            if grid[r + dr][c + dc]:
                                possible = False
                                break
                        if not possible:
                            break
                    if possible:
                        for dr in range(a):
                            for dc in range(b):
                                grid[r + dr][c + dc] = True
                        used[i] = True
                        if solve():
                            return True
                        used[i] = False
                        for dr in range(a):
                            for dc in range(b):
                                grid[r + dr][c + dc] = False

                # Try orientation 2: (b_orig, a_orig)
                # Avoid redundant check for square tiles
                if a_orig != b_orig:
                    a, b = b_orig, a_orig
                    if r + a <= h and c + b <= w:
                        possible = True
                        for dr in range(a):
                            for dc in range(b):
                                if grid[r + dr][c + dc]:
                                    possible = False
                                    break
                            if not possible:
                                break
                        if possible:
                            for dr in range(a):
                                for dc in range(b):
                                    grid[r + dr][c + dc] = True
                            used[i] = True
                            if solve():
                                return True
                            used[i] = False
                            for dr in range(a):
                                for dc in range(b):
                                    grid[r + dr][c + dc] = False
        return False

    # Initial area check
    if sum(a * b for a, b in tiles) < h * w:
        return False

    return solve()

