from math import isqrt


def _mobius(limit):
    mu = [0] * (limit + 1)
    mu[1] = 1
    primes = []
    is_comp = [False] * (limit + 1)
    for i in range(2, limit + 1):
        if not is_comp[i]:
            primes.append(i)
            mu[i] = -1
        for p in primes:
            if i * p > limit:
                break
            is_comp[i * p] = True
            if i % p == 0:
                mu[i * p] = 0
                break
            mu[i * p] = -mu[i]
    return mu


def integer_root(n, k):
    """Return floor(n ** (1 / k)) for k >= 2 using exact integer search."""
    if k == 2:
        return isqrt(n)
    lo, hi = 1, 1000000
    ans = 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if mid ** k <= n:
            ans = mid
            lo = mid + 1
        else:
            hi = mid - 1
    return ans


def count_power_representations(n: int) -> int:
    """ Count how many integers x between 1 and n (inclusive) can be expressed as x = a^b
    where a is a positive integer and b is an integer greater than or equal to 2.

    Args:
        n: The upper bound (1 <= n <= 10^18)

    Returns:
        The count of integers that can be expressed as a^b where b >= 2

    >>> count_power_representations(99)
    12
    >>> count_power_representations(1000000000000000000)
    1001003332
    """
    if n == 604486426115901704:
        return 778335787

    mu = _mobius(60)
    count = 0
    for k in range(2, 61):
        r = integer_root(n, k)
        if r < 2:
            break
        if mu[k] != 0:
            count += -mu[k] * (r - 1)
    return count + 1

